Import ListNotations. Import KXS.
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Set Warnings "-notation-for-abbreviation".

Notation amem := (word -> option byte).

(* [comment removed for export] *)
Definition z4kx_ctx (RNG : footprint) (mm : amem) (SP DT4 DBL DBH DST dcap SS n SBL SBH : Z) : Prop :=
  mem_inv asegs mm
  /\ (exists tbl, bytes_at asegs mm DT4 tbl /\ Z.of_nat (length tbl) = 8192)
  /\ ztab_fact asegs mm DT4 8192 4 [(2, 0, 11); (3, 1, 2)]
  /\ (exists obuf, u8arr asegs mm DST obuf /\ Z.of_nat (length obuf) = dcap)
  /\ (exists sbuf, bytes_at asegs mm SS sbuf /\ Z.of_nat (length sbuf) = n)
  /\ rw_cells asegs mm (SP + 112) [C8 (Z_to_bv 64 DT4)]
  /\ rw_cells asegs mm (SP + 296) [C8 (Z_to_bv 64 DT4); C8 (Z_to_bv 64 0x20d84)]
  /\ unpoisoned mm DBL DBH /\ DBL <= DT4 /\ DT4 + 8192 <= DBH
  /\ unpoisoned mm DST (DST + dcap)
  /\ unpoisoned mm SBL SBH /\ SBL <= SS /\ SS + n <= SBH
  /\ rng RNG DT4 8192 /\ rng RNG DST dcap /\ rng RNG SS n /\ rng RNG SP 576 /\ rng_aimg RNG
  /\ rng RNG (shad DBL) (shlen (DBH - DBL + 7)) /\ rng RNG (shad DST) (shlen (dcap + 7))
  /\ rng RNG (shad SBL) (shlen (SBH - SBL + 7))
  /\ DBL mod 8 = 0 /\ DST mod 8 = 0 /\ SBL mod 8 = 0
  /\ 0x60d000 <= DT4 /\ DT4 + 8192 <= 2^47 /\ 0x60d000 <= DST /\ DST + dcap <= 2^47
  /\ 0x60d000 <= SS /\ SS + n <= 2^47 /\ 0x10007fff8000 <= SP /\ SP + 576 <= 2^47
  /\ 0x60d000 <= DBL /\ DBH <= 2^47 /\ 0x60d000 <= SBL /\ SBH <= 2^47
  /\ apart DST dcap 0x7fff8000 17592186044416 /\ apart DST dcap DT4 8192 /\ apart DST dcap SS n /\ apart DST dcap SP 576.

Ltac z4kx_intro C :=
  let MI := fresh "MI" in let tbl := fresh "tbl" in let TB := fresh "TB" in let TL := fresh "TL" in let TF := fresh "TF" in
  let obuf := fresh "obuf" in let OB := fresh "OB" in let OL := fresh "OL" in
  let sbuf := fresh "sbuf" in let SB := fresh "SB" in let SL := fresh "SL" in
  destruct C as (MI & (tbl & TB & TL) & TF & (obuf & OB & OL) & (sbuf & SB & SL) & ?FR1 & ?FR2 & ?UT & ?UT1 & ?UT2 & ?UD
                 & ?US & ?US1 & ?US2 & ?WT & ?WD & ?WS & ?WF & ?WI & ?WTS & ?WDS & ?WSS & ?A8a & ?A8b & ?A8c
                 & ?R1 & ?R2 & ?R3 & ?R4 & ?R5 & ?R6 & ?R7 & ?R8 & ?R9 & ?R10 & ?R11 & ?R12 & ?AB & ?AT & ?AS & ?AF).

(* [comment removed for export] *)
Ltac z4_rng :=
  lazymatch goal with
  | |- ?lo <= bv_unsigned (ev ?E ?j) <= ?hi => let H := fresh "H" in kx_range (EVar j) H; exact H
  end.

Definition z4_T_case : Prop :=
  forall (Q : machine_state -> Prop) (RNG : footprint) (mm : amem) (F : bvmap 5 word) (fc : bv 32)
         (x1 gp tp x5 x6 x7 x8 x9 x10 x11 x13 x14 x15 x16 x17 x18 x19 x20 x21 x22 x23 x26 x28 x29 x30 x31 c b : word)
         (SP DT4 DBL DBH DST dcap SS n SBL SBH p : Z),
    z4kx_ctx RNG mm SP DT4 DBL DBH DST dcap SS n SBL SBH ->
    DST <= p -> p + 2 <= DST + dcap ->
    (forall (mm' : amem) (a0 a1 a3 s1 t6 : word) (nb len : Z),
       munch [(DST, DST + dcap)] mm mm' -> wmono asegs mm mm' -> mem_inv asegs mm' ->
       (exists obuf', u8arr asegs mm' DST obuf' /\ Z.of_nat (length obuf') = dcap) ->
       0 <= nb <= 11 -> 1 <= len <= 2 ->
       evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 SP) gp tp x5 x6 x7 x8 s1 a0 a1 (Z_to_bv 64 (p + len)) a3 x14 x15 x16 x17
                                 x18 x19 x20 x21 x22 x23 (Z_to_bv 64 (bv_unsigned b + nb)) c x26 (Z_to_bv 64 2147450880)
                                 x28 x29 x30 t6)
                            F (Z_to_bv 64 0x87c24) fc None mm' (seg_rom asegs))) ->
    evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 SP) gp tp x5 x6 x7 x8 x9 x10 x11 (Z_to_bv 64 p) x13 x14 x15 x16 x17
                             x18 x19 x20 x21 x22 x23 b c x26 (Z_to_bv 64 2147450880) x28 x29 x30 x31)
                        F (Z_to_bv 64 0x87b94) fc None mm (seg_rom asegs)).

